import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"小牛翻译接口申请及配置","description":"","frontmatter":{"plugin":"windingwind/zotero-pdf-translate"},"headers":[],"relativePath":"user-guide/plugins/translate/niutrans.md","filePath":"wiki/user-guide/plugins/translate/niutrans.md"}`),u=Object.assign({name:`user-guide/plugins/translate/niutrans.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginstranslateniutrans.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`小牛翻译接口申请及配置`,tabindex:`-1`},[o(`小牛翻译接口申请及配置 `),i(`a`,{class:`header-anchor`,href:`#小牛翻译接口申请及配置`,"aria-label":`Permalink to “小牛翻译接口申请及配置”`},`​`)],-1),r(s),u[2]||=a(`<p>小牛翻译团队源自东北大学 NLP 实验室，深耕自然语言处理领域数十年，支持 454 种语言互译，拥有极速响应、高并发、高精度的翻译特性，可满足论文、文献等科研场景以及各类行业的翻译需求，面向科研用户提供稳定的翻译 API 服务。</p><h2 id="免费额度说明" tabindex="-1">免费额度说明 <a class="header-anchor" href="#免费额度说明" aria-label="Permalink to “免费额度说明”">​</a></h2><p>新用户注册即可领取 500 积分（100 万字符）；平台每日额外发放 100 积分（20 万字符）免费额度。</p><p>小牛翻译专为 Zotero 中文社区用户提供专属福利：通过社区专属链接注册，可额外再领取 500 积分。</p><p>社区用户注册总计可获得 1000 积分（等价 200 万字符），具体注册操作详见下文账号注册说明。</p><h2 id="计费规则" tabindex="-1">计费规则 <a class="header-anchor" href="#计费规则" aria-label="Permalink to “计费规则”">​</a></h2><p>免费额度使用完毕后，可选购通用积分包或字符流量包来调用翻译 API：</p><ul><li>通用积分包：30 元可购买 300 积分，90 元可购买 900 积分；1 积分可完成 2000 字符翻译。</li><li>字符流量包：500 元可购买 1000 万字符额度，按照实际翻译消耗的字符数量扣费。</li></ul><h2 id="账号使用提示" tabindex="-1">账号使用提示 <a class="header-anchor" href="#账号使用提示" aria-label="Permalink to “账号使用提示”">​</a></h2><p>小牛翻译云平台与 Zotero 翻译插件账号互通。注册账号后，可通过账号密码在 Zotero 翻译插件中登录；APIKEY 可在开放平台个人中心查看。</p><h2 id="_1-账号注册" tabindex="-1">1. 账号注册 <a class="header-anchor" href="#_1-账号注册" aria-label="Permalink to “1. 账号注册”">​</a></h2><p>访问<a href="https://niutrans.com/login?active=3&amp;userSource=zotero" target="_blank" rel="noreferrer">小牛翻译开放平台专属注册链接</a>，输入相应注册信息，点击「注册」。</p><p><img src="/assets/niutrans-register.pIzpRr89.png" alt="小牛翻译开放平台注册入口" width="1920" height="1041"></p><h2 id="_2-完善账号信息" tabindex="-1">2. 完善账号信息 <a class="header-anchor" href="#_2-完善账号信息" aria-label="Permalink to “2. 完善账号信息”">​</a></h2><p>注册完成后，进入「控制台」→「个人中心」，完成基础信息填写并领取 500 积分礼包。</p><p><img src="/assets/niutrans-profile.CdZmcNHY.png" alt="小牛翻译个人中心" width="1920" height="946"></p><h2 id="_3-zotero-翻译插件小牛翻译服务设置" tabindex="-1">3. Zotero 翻译插件小牛翻译服务设置 <a class="header-anchor" href="#_3-zotero-翻译插件小牛翻译服务设置" aria-label="Permalink to “3. Zotero 翻译插件小牛翻译服务设置”">​</a></h2><p>打开 Zotero 客户端，并打开设置，在翻译服务下拉菜单中选择「小牛」，点击右侧「配置」按钮。</p><p><img src="/assets/zotero-niutrans-service.DhTAojAe.png" alt="Zotero 翻译插件小牛服务" width="1376" height="1080"></p><p>在输入框中填写刚刚注册的账号和密码。填写完成后保存设置即可生效。</p><p><img src="/assets/niutrans-settings.D72OfjBP.png" alt="Zotero 翻译插件小牛翻译服务设置" width="546" height="459"></p><h2 id="_4-接口测试" tabindex="-1">4. 接口测试 <a class="header-anchor" href="#_4-接口测试" aria-label="Permalink to “4. 接口测试”">​</a></h2><p>全部配置完成后，可进行接口可用性测试。在 Zotero 中打开任意外文 PDF 文献，选中段落或专业词汇进行划词翻译或右键翻译。</p><p>若页面正常输出通顺、准确的中文译文，且无报错、无空白内容，即代表小牛翻译接口配置成功，可以正常使用。</p><h2 id="_5-查询数据使用情况" tabindex="-1">5. 查询数据使用情况 <a class="header-anchor" href="#_5-查询数据使用情况" aria-label="Permalink to “5. 查询数据使用情况”">​</a></h2><p>进入「<a href="https://niutrans.com/cloud/overview" target="_blank" rel="noreferrer">控制台</a>」→「数据统计」，即可查看翻译接口的用量情况。</p><p><img src="/assets/niutrans-statistics.xsbU8vpw.png" alt="小牛翻译数据统计" width="1920" height="945"></p><h2 id="_6-购买字符流量或通用积分" tabindex="-1">6. 购买字符流量或通用积分 <a class="header-anchor" href="#_6-购买字符流量或通用积分" aria-label="Permalink to “6. 购买字符流量或通用积分”">​</a></h2><p>登录小牛翻译云平台，进入「<a href="https://niutrans.com/price?type=integral" target="_blank" rel="noreferrer">充值中心</a>」，可购买所需的字符流量或通用积分。</p><p><img src="/assets/niutrans-recharge.BBvYsPJV.png" alt="小牛翻译充值中心" width="1376" height="1080"></p>`,30),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};